SELECT agg.i_brand, agg.i_category, agg.total_sales, agg.total_returns, agg.total_sales - agg.total_returns AS net_balance FROM ( SELECT i.i_brand, i.i_category, SUM(ss_sub.ss_net_paid) AS total_sales, SUM(sr.sr_return_amt) AS total_returns FROM ( SELECT ss_item_sk, ss_sold_date_sk, ss_net_paid FROM store_sales WHERE ss_sold_date_sk = CAST(2452420 AS integer) ) ss_sub JOIN item i ON ss_sub.ss_item_sk = i.i_item_sk JOIN store_returns sr ON sr.sr_item_sk = i.i_item_sk JOIN inventory inv ON inv.inv_item_sk = i.i_item_sk GROUP BY i.i_brand, i.i_category HAVING i.i_brand = 'amalgmaxi #12                                     ' ) agg
